function o(a){return a.toISOString().split("T")[0]}function c(){return o(new Date)}function g(a){const t=new Date,r=o(t);let e;switch(a){case"week":{e=new Date(t);const n=e.getDay()||7;e.setDate(e.getDate()-n+1);break}case"month":e=new Date(t.getFullYear(),t.getMonth(),1);break;case"quarter":{const n=Math.floor(t.getMonth()/3);e=new Date(t.getFullYear(),n*3,1);break}case"half-year":{const n=t.getMonth()<6?0:6;e=new Date(t.getFullYear(),n,1);break}case"year":e=new Date(t.getFullYear(),0,1);break}return{start:o(e),end:r}}function i(a){if(!a)return"--:--";const t=new Date(a);return isNaN(t.getTime())?"--:--":t.toLocaleTimeString("zh-CN",{hour:"2-digit",minute:"2-digit",hour12:!1})}function u(a){const t=new Date(a+"T00:00:00"),r=["日","一","二","三","四","五","六"],e=t.getMonth()+1,n=t.getDate(),s=r[t.getDay()];return`${e}月${n}日 周${s}`}export{i as a,c as b,u as f,g};
